bash -lc "node - <<'NODE'
const { chromium } = require('playwright-chromium');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1240, height: 1754 }, deviceScaleFactor: 2 });
  const filePath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(filePath, { waitUntil: 'load' });

  // wait for the infographic to render and be ready
  await page.waitForFunction(() => {
    const c = document.querySelector('#container');
    return !!(c && c.querySelector('svg'));
  }, { timeout: 30000 });

  // Add a bit of padding by scaling container via CSS? We'll just screenshot full viewport.
  await page.screenshot({ path: '/app/output/final_poster.png', fullPage: false });

  await browser.close();
  const stat = fs.statSync('/app/output/final_poster.png');
  console.log('wrote', stat.size);
})();
NODE"

